'use client';
import {InvoiceReversalAction} from '@/components/invoice-reversal-action';
import {InvoiceAllocationAction} from '@/components/invoice-allocation-action';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import {readInvoiceAllocationHistory,readInvoicePaymentOptions} from '@/lib/invoice-payment-options';
type Props={tenant:string;property:string;invoice:string;actor:string;disabled:boolean};
export function InvoicePaymentReview(props:Props){return <Review key={[props.tenant,props.property,props.invoice,props.actor].join(':')} {...props}/>;}
function Review({disabled,...scope}:Props){
 const [review,setReview]=useState<ReturnType<typeof readInvoicePaymentOptions>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[options,setOptions]=useState<unknown>(null),[historySource,setHistorySource]=useState<unknown>(null),[history,setHistory]=useState<ReturnType<typeof readInvoiceAllocationHistory>|null>(null);const alive=useRef(false),lock=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false;};},[]);
 async function load(loadHistory=false){if(disabled||lock.current)return;lock.current=true;setBusy(true);setReview(null);setHistory(null);setOptions(null);setHistorySource(null);setError('');try{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen the invoice.');if(!alive.current)return;
 const result=await hotelRpc<unknown>(loadHistory?'invoice_allocations':'invoice_payment_options',{p_tenant:scope.tenant,p_property:scope.property,p_invoice:scope.invoice}),again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen the invoice.');if(alive.current){if(loadHistory){setHistory(readInvoiceAllocationHistory(result,scope));setHistorySource(result);}else {setReview(readInvoicePaymentOptions(result,scope));setOptions(result);}}
 }catch(cause){if(alive.current)setError(cause instanceof Error?cause.message:'Unable to review payments.');}finally{lock.current=false;if(alive.current)setBusy(false);}}
 return <section className="pilot-settings"><h3>Invoice payment review</h3><p>Review recorded payments available to apply to this invoice.</p><button disabled={busy||disabled} onClick={()=>void load()}>Review available payments</button><button disabled={busy||disabled} onClick={()=>void load(true)}>Load allocation history</button>{error&&<p role="alert">{error}</p>}{review&&<><p>Invoice outstanding: {usd(Number(review.outstanding_minor))}</p>{review.payments.length===0?<p>No recorded payments for this stay.</p>:<table className="pilot-table"><thead><tr><th>Receipt</th><th>Received</th><th>Refunded / corrected</th><th>Applied</th><th>Available</th><th>Maximum for this invoice</th></tr></thead><tbody>{review.payments.map(p=><tr key={p.entry_id}><td>{p.reference}</td><td>{usd(Number(p.received_minor))}</td><td>{usd(Number(p.reduced_minor))}</td><td>{usd(Number(p.allocated_minor))}</td><td>{usd(Number(p.available_minor))}</td><td>{usd(Number(p.maximum_minor))}</td></tr>)}</tbody></table>}</>}{history&&<><h4>Allocation history</h4>{history.length===0?<p>No payments applied to this invoice.</p>:<table className="pilot-table"><thead><tr><th>Receipt</th><th>Effective date</th><th>Applied</th><th>Reversed</th><th>Remaining reversible</th><th>Reason</th></tr></thead><tbody>{history.map(a=><tr key={a.id}><td>{a.reference}</td><td>{a.effective_on}</td><td>{usd(Number(a.amount_minor))}</td><td>{usd(Number(a.reversed_minor))}</td><td>{usd(Number(a.reversible_minor))}</td><td>{a.reason}</td></tr>)}</tbody></table>}</>}<InvoiceAllocationAction {...scope} disabled={busy||disabled} options={options}/><InvoiceReversalAction {...scope} disabled={busy||disabled} options={historySource}/></section>;
}
